using Throttling;

int inFlight = 0;
int maxObserved = 0;
object gate = new();

Func<Task<int>> Make(int i) => async () =>
{
    lock (gate) { inFlight++; maxObserved = Math.Max(maxObserved, inFlight); }
    await Task.Delay(100);
    lock (gate) { inFlight--; }
    return i * 10;
};

var factories = new List<Func<Task<int>>>();
for (int i = 0; i < 9; i++) factories.Add(Make(i));

var sw = System.Diagnostics.Stopwatch.StartNew();
int[] results = await Limiter.RunLimited(factories, 3);
sw.Stop();

if (maxObserved > 3)
{
    Console.Error.WriteLine($"observed {maxObserved} concurrent tasks, limit was 3");
    Environment.Exit(1);
}
if (maxObserved < 2)
{
    Console.Error.WriteLine($"observed only {maxObserved} concurrent task(s) - not actually parallel");
    Environment.Exit(1);
}
for (int i = 0; i < 9; i++)
{
    if (results[i] != i * 10)
    {
        Console.Error.WriteLine($"results[{i}] = {results[i]}, want {i * 10} (factory order)");
        Environment.Exit(1);
    }
}
// 9 tasks x 100ms at limit 3 => ~300ms; sequential would be ~900ms.
if (sw.ElapsedMilliseconds >= 700)
{
    Console.Error.WriteLine($"took {sw.ElapsedMilliseconds}ms - limiter is serializing everything");
    Environment.Exit(1);
}

// throwing factories must RELEASE their permit - two throws at limit 2
// would otherwise exhaust the semaphore and deadlock the remaining tasks.
int completed = 0;
var mixed = new List<Func<Task<int>>>
{
    async () => { await Task.Delay(10); throw new InvalidOperationException("boom-1"); },
    async () => { await Task.Delay(10); throw new InvalidOperationException("boom-2"); },
    async () => { await Task.Delay(10); Interlocked.Increment(ref completed); return 3; },
    async () => { await Task.Delay(10); Interlocked.Increment(ref completed); return 4; },
};
var run = Limiter.RunLimited(mixed, 2);
var winner = await Task.WhenAny(run, Task.Delay(5000));
if (winner != run)
{
    Console.Error.WriteLine("RunLimited deadlocked after throwing factories - permits are not released on throw");
    Environment.Exit(1);
}
try
{
    await run;
    Console.Error.WriteLine("expected the exception to be rethrown");
    Environment.Exit(1);
}
catch (InvalidOperationException)
{
    if (completed != 2)
    {
        Console.Error.WriteLine($"only {completed} non-throwing factories completed - a failure must not cancel the rest");
        Environment.Exit(1);
    }
}

Console.WriteLine("PASS");

