namespace Throttling;

public static class Limiter
{
    public static async Task<T[]> RunLimited<T>(IReadOnlyList<Func<Task<T>>> taskFactories, int maxConcurrency)
    {
        using var semaphore = new SemaphoreSlim(maxConcurrency);
        var tasks = new Task<T>[taskFactories.Count];
        for (int i = 0; i < taskFactories.Count; i++)
        {
            var factory = taskFactories[i];
            tasks[i] = Run(factory);
        }

        Exception? first = null;
        var results = new T[tasks.Length];
        for (int i = 0; i < tasks.Length; i++)
        {
            try
            {
                results[i] = await tasks[i];
            }
            catch (Exception e)
            {
                first ??= e;
            }
        }
        if (first != null) throw first;
        return results;

        async Task<T> Run(Func<Task<T>> factory)
        {
            await semaphore.WaitAsync();
            try
            {
                return await factory();
            }
            finally
            {
                semaphore.Release();
            }
        }
    }
}

